PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE alertas_asistencia (
	id_alerta VARCHAR(36) NOT NULL, 
	id_evento VARCHAR(36) NOT NULL, 
	tipo_estimulo VARCHAR(15) NOT NULL, 
	timestamp DATETIME NOT NULL, 
	reenganche_exitoso BOOLEAN, 
	PRIMARY KEY (id_alerta), 
	FOREIGN KEY(id_evento) REFERENCES eventos_desatencion (id_evento)
);
CREATE TABLE auditoria_consentimientos (
	id_consentimiento VARCHAR(36) NOT NULL, 
	id_usuario VARCHAR(36) NOT NULL, 
	rol_usuario VARCHAR(10) NOT NULL, 
	codigo_estudiante_asociado VARCHAR(20), 
	version_documento VARCHAR(20) NOT NULL, 
	ip_registro VARCHAR(45), 
	user_agent VARCHAR(255), 
	fecha_hora DATETIME NOT NULL, 
	PRIMARY KEY (id_consentimiento), 
	FOREIGN KEY(id_usuario) REFERENCES usuarios (id_usuario)
);
CREATE TABLE cursos (
	id_curso VARCHAR(36) NOT NULL, 
	nombre_curso VARCHAR(100) NOT NULL, 
	nivel_academico VARCHAR(50) NOT NULL, 
	descripcion VARCHAR(200), 
	activo BOOLEAN NOT NULL, 
	fecha_creacion DATETIME, 
	PRIMARY KEY (id_curso)
);
CREATE TABLE docente_cursos (
	id_asignacion VARCHAR(36) NOT NULL, 
	id_docente VARCHAR(36) NOT NULL, 
	id_curso VARCHAR(36) NOT NULL, 
	fecha_asignacion DATETIME, 
	PRIMARY KEY (id_asignacion), 
	FOREIGN KEY(id_docente) REFERENCES usuarios (id_usuario), 
	FOREIGN KEY(id_curso) REFERENCES cursos (id_curso)
);
CREATE TABLE estudiantes (
	id_estudiante VARCHAR(36) NOT NULL, 
	codigo_estudiante VARCHAR(20) NOT NULL, 
	nombre_completo VARCHAR(100) NOT NULL, 
	edad INTEGER, 
	grado_escolar VARCHAR(50), 
	diagnostico_observacion TEXT, 
	fecha_registro DATETIME, 
	id_usuario VARCHAR(36), subtipo_tdah VARCHAR(20) DEFAULT 'combined', protegido BOOLEAN DEFAULT 1, id_tutor VARCHAR(36), 
	PRIMARY KEY (id_estudiante), 
	FOREIGN KEY(id_usuario) REFERENCES usuarios (id_usuario)
);
CREATE TABLE eventos_desatencion (
	id_evento VARCHAR(36) NOT NULL, 
	id_sesion VARCHAR(36) NOT NULL, 
	tipo_evento VARCHAR(16) NOT NULL, 
	severidad VARCHAR(8) NOT NULL, 
	timestamp_inicio DATETIME NOT NULL, 
	timestamp_fin DATETIME, 
	duracion_segundos FLOAT, ruta_captura VARCHAR(300), minuto_relativo VARCHAR(20), descripcion_automatica VARCHAR(300), ruta_captura_pantalla VARCHAR(300), 
	PRIMARY KEY (id_evento), 
	FOREIGN KEY(id_sesion) REFERENCES sesiones_monitoreo (id_sesion)
);
CREATE TABLE materiales_estudio (
	id_material VARCHAR(36) NOT NULL, 
	titulo VARCHAR(150) NOT NULL, 
	descripcion_tarea TEXT, 
	id_curso VARCHAR(36), 
	id_docente VARCHAR(36), 
	codigo_estudiante_propietario VARCHAR(20), 
	nombre_archivo_original VARCHAR(200) NOT NULL, 
	nombre_pdf VARCHAR(200) NOT NULL, 
	url_pdf VARCHAR(255) NOT NULL, 
	extension_original VARCHAR(10) NOT NULL, 
	tamano_kb FLOAT, 
	fecha_subida DATETIME, 
	PRIMARY KEY (id_material), 
	FOREIGN KEY(id_curso) REFERENCES cursos (id_curso), 
	FOREIGN KEY(id_docente) REFERENCES usuarios (id_usuario)
);
CREATE TABLE metricas_atencionales (
    id_metrica INTEGER PRIMARY KEY AUTOINCREMENT,
    id_sesion VARCHAR(36) NOT NULL,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
    valor_ear FLOAT NOT NULL,
    angulo_yaw FLOAT NOT NULL,
    angulo_pitch FLOAT NOT NULL,
    varianza_cinematica FLOAT NOT NULL,
    indice_iai FLOAT NOT NULL,
    estado_atencion VARCHAR(12) NOT NULL,
    FOREIGN KEY(id_sesion) REFERENCES sesiones_monitoreo (id_sesion)
);
CREATE TABLE parametros_calibracion (
	id_calibracion VARCHAR(36) NOT NULL, 
	id_sesion VARCHAR(36) NOT NULL, 
	ear_base FLOAT NOT NULL, 
	pitch_neutral FLOAT NOT NULL, 
	yaw_neutral FLOAT NOT NULL, 
	roll_neutral FLOAT NOT NULL, 
	varianza_hombros_base FLOAT NOT NULL, 
	fecha_calibracion DATETIME, 
	PRIMARY KEY (id_calibracion), 
	UNIQUE (id_sesion), 
	FOREIGN KEY(id_sesion) REFERENCES sesiones_monitoreo (id_sesion)
);
CREATE TABLE permisos (
	id_permiso VARCHAR(36) NOT NULL, 
	codigo_permiso VARCHAR(50) NOT NULL, 
	nombre_permiso VARCHAR(100) NOT NULL, 
	descripcion VARCHAR(255), 
	modulo VARCHAR(30) NOT NULL, 
	fecha_creacion DATETIME, 
	PRIMARY KEY (id_permiso)
);
CREATE TABLE reportes_psicopedagogicos (
	id_reporte VARCHAR(36) NOT NULL, 
	id_sesion VARCHAR(36) NOT NULL, 
	fecha_generacion DATETIME NOT NULL, 
	porcentaje_atencion_alta FLOAT, 
	total_eventos_inquietud INTEGER, 
	observaciones_psicopedagogicas TEXT, 
	ruta_archivo_pdf VARCHAR(255), 
	PRIMARY KEY (id_reporte), 
	UNIQUE (id_sesion), 
	FOREIGN KEY(id_sesion) REFERENCES sesiones_monitoreo (id_sesion)
);
CREATE TABLE roles (
	id_rol VARCHAR(36) NOT NULL, 
	nombre_rol VARCHAR(50) NOT NULL, 
	descripcion VARCHAR(255), 
	es_sistema BOOLEAN NOT NULL, 
	fecha_creacion DATETIME, 
	PRIMARY KEY (id_rol)
);
CREATE TABLE roles_permisos (
	id_rol VARCHAR(36) NOT NULL, 
	id_permiso VARCHAR(36) NOT NULL, 
	fecha_asignacion DATETIME, 
	PRIMARY KEY (id_rol, id_permiso), 
	FOREIGN KEY(id_rol) REFERENCES roles (id_rol) ON DELETE CASCADE, 
	FOREIGN KEY(id_permiso) REFERENCES permisos (id_permiso) ON DELETE CASCADE
);
CREATE TABLE sesiones_monitoreo (
	id_sesion VARCHAR(36) NOT NULL, 
	id_estudiante VARCHAR(36) NOT NULL, 
	fecha_hora_inicio DATETIME NOT NULL, 
	fecha_hora_fin DATETIME, 
	duracion_segundos INTEGER, 
	limite_tiempo_segundos INTEGER, 
	auto_cerrada BOOLEAN, 
	estado_sesion VARCHAR(10), 
	promedio_iai FLOAT, 
	PRIMARY KEY (id_sesion), 
	FOREIGN KEY(id_estudiante) REFERENCES estudiantes (id_estudiante)
);
CREATE TABLE usuarios (
	id_usuario VARCHAR(36) NOT NULL, 
	username VARCHAR(50) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	email VARCHAR(100) NOT NULL, 
	rol VARCHAR(10) NOT NULL, 
	fecha_creacion DATETIME, acepto_terminos BOOLEAN DEFAULT 0 NOT NULL, fecha_aceptacion_terminos DATETIME, version_terminos VARCHAR(20) DEFAULT '1.0-2026', id_rol VARCHAR(36), verificado BOOLEAN DEFAULT 0 NOT NULL, activo BOOLEAN DEFAULT 1 NOT NULL, 
	PRIMARY KEY (id_usuario)
);
CREATE UNIQUE INDEX ix_usuarios_username ON usuarios (username);
CREATE UNIQUE INDEX ix_usuarios_email ON usuarios (email);
CREATE UNIQUE INDEX ix_estudiantes_codigo_estudiante ON estudiantes (codigo_estudiante);
CREATE INDEX ix_sesiones_monitoreo_id_estudiante ON sesiones_monitoreo (id_estudiante);
CREATE INDEX ix_eventos_desatencion_id_sesion ON eventos_desatencion (id_sesion);
CREATE INDEX ix_alertas_asistencia_id_evento ON alertas_asistencia (id_evento);
CREATE INDEX ix_metricas_id_sesion ON metricas_atencionales (id_sesion);
CREATE INDEX ix_metricas_timestamp ON metricas_atencionales (timestamp);
CREATE INDEX ix_auditoria_consentimientos_id_usuario ON auditoria_consentimientos (id_usuario);
CREATE UNIQUE INDEX ix_cursos_nombre_curso ON cursos (nombre_curso);
CREATE UNIQUE INDEX ix_roles_nombre_rol ON roles (nombre_rol);
CREATE UNIQUE INDEX ix_permisos_codigo_permiso ON permisos (codigo_permiso);
CREATE INDEX ix_docente_cursos_id_docente ON docente_cursos (id_docente);
CREATE INDEX ix_docente_cursos_id_curso ON docente_cursos (id_curso);
CREATE INDEX ix_materiales_estudio_codigo_estudiante_propietario ON materiales_estudio (codigo_estudiante_propietario);
CREATE INDEX ix_materiales_estudio_id_docente ON materiales_estudio (id_docente);
CREATE INDEX ix_materiales_estudio_id_curso ON materiales_estudio (id_curso);
DELETE FROM "sqlite_sequence";
COMMIT;
